// KTX2 output of `forge generate` (vegetation plan PG3, §8: generated atlases
// are compressed; user decision 2026-11-19: the generator writes .ktx2
// directly, no PNG). UASTC LDR 4 × 4 (8 bits per texel on the GPU: BC7 on
// desktop, ASTC / ETC2 elsewhere through three's KTX2Loader transcoder),
// Zstandard supercompression, the mip chain generated by the encoder (a
// compressed texture gets no runtime mips). The basis encoder is the WebAssembly
// build `ktx2-encoder` pins; single-threaded, the same input gives the same
// bytes (generate.test.ts).
//
// Orientation: the first row of `rgba` is the top of the image, as the PNG
// writer has it. textures.ts uploads every image unflipped and a material flips
// V for an uncompressed image only (surfaceMaterial.ts), so a texture a
// flipping material samples is stored flipped (`flipY`); one read with its own
// coordinates (an impostor atlas) is stored as is.

import { encodeToKTX2 } from "ktx2-encoder";

export interface Ktx2Options {
  /** Colour data (sRGB transfer, perceptual error metric); false for linear data (normals, depth, thresholds). */
  readonly srgb: boolean;
  /** Store the image upside down: for a texture a `flipY` material samples. */
  readonly flipY?: boolean;
}

/** UASTC effort 0..4: 1 is the encoder's default ("faster"), about 2 s for 2048 × 1024 with mips. */
const UASTC_EFFORT = 1;

export async function encodeRgbaKtx2(width: number, height: number, rgba: Uint8Array, options: Ktx2Options): Promise<Uint8Array> {
  if (!Number.isInteger(width) || !Number.isInteger(height) || width < 1 || height < 1 || rgba.length !== width * height * 4) {
    throw new Error(`encodeRgbaKtx2: ${rgba.length} bytes do not make a ${width} × ${height} RGBA image`);
  }
  // The WebAssembly encoder prints its progress through console.log whatever its debug flag says.
  const log = console.log;
  console.log = () => {};
  try {
    return await encodeToKTX2(new Uint8Array(0), {
      isUASTC: true,
      uastcLDRQualityLevel: UASTC_EFFORT,
      needSupercompression: true,
      generateMipmap: true,
      isKTX2File: true,
      isSetKTX2SRGBTransferFunc: options.srgb,
      isPerceptual: options.srgb,
      isYFlip: options.flipY === true,
      imageDecoder: async () => ({ width, height, data: rgba }),
    });
  } finally {
    console.log = log;
  }
}
